        not key_version
        or any(ch < "0" or ch > "9" for ch in key_version)
        or int(key_version) < 1
    ):
        raise ValidationError("路径参数 key_version 必须为正整数")
    record = store.revoke_trust_anchor(tenant, did, int(key_version))
